import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"23 - IP Security","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/23-ip-security.md","filePath":"developers/design-documentation/23-ip-security.md"}'),o={name:"developers/design-documentation/23-ip-security.md"};function i(n,t,s,c,l,h){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_23-ip-security" tabindex="-1">23 - IP Security <a class="header-anchor" href="#_23-ip-security" aria-label="Permalink to &quot;23 - IP Security&quot;">​</a></h1><h2 id="request-boundary" tabindex="-1">Request Boundary <a class="header-anchor" href="#request-boundary" aria-label="Permalink to &quot;Request Boundary&quot;">​</a></h2><p><code>SecurityMiddleware</code> checks the resolved client IP against <code>logs.db</code> before Flask handles the request. An active ban returns plain-text HTTP 403 and removes the scoped logs session on both blocked and allowed paths.</p><p>Client-IP resolution is deliberately gated by <code>TRUST_PROXY_HEADERS</code>:</p><ul><li>Default <code>FALSE</code>: use only the immediate peer (<code>REMOTE_ADDR</code> / <code>request.remote_addr</code>).</li><li><code>TRUE</code>: accept <code>CF-Connecting-IP</code>, <code>True-Client-IP</code>, <code>X-Real-IP</code>, the first <code>X-Forwarded-For</code> value, then <code>X-Client-IP</code>.</li></ul><p>Enable forwarded headers only when a controlled reverse proxy is the sole route to Gunicorn/Flask. Otherwise a direct client can spoof those headers and evade per-IP controls.</p><h2 id="stored-security-state" tabindex="-1">Stored Security State <a class="header-anchor" href="#stored-security-state" aria-label="Permalink to &quot;Stored Security State&quot;">​</a></h2><p><code>database/traffic_db.py</code> stores three IP-related domains in <code>logs.db</code>:</p><table tabindex="0"><thead><tr><th>Table</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ip_bans</code></td><td>Active temporary or permanent bans, reason, count, creator</td></tr><tr><td><code>error_404_tracker</code></td><td>Per-IP 404 count and up to 50 distinct attempted paths in a 24-hour window</td></tr><tr><td><code>invalid_api_key_tracker</code></td><td>Per-IP invalid-key count and up to 20 key hashes in a 24-hour window</td></tr></tbody></table><p>Raw API keys are not stored by the invalid-key tracker.</p><p>Ban lookups use a short TTL cache. Manual ban/unban and automatic changes invalidate the affected cache entry.</p><h2 id="automatic-bans" tabindex="-1">Automatic Bans <a class="header-anchor" href="#automatic-bans" aria-label="Permalink to &quot;Automatic Bans&quot;">​</a></h2><p>Automatic bans are controlled by the persisted Security settings, not environment variables. Current defaults are:</p><table tabindex="0"><thead><tr><th>Setting</th><th style="text-align:right;">Default</th></tr></thead><tbody><tr><td>Automatic banning</td><td style="text-align:right;">Off</td></tr><tr><td>404 threshold in 24 hours</td><td style="text-align:right;">100</td></tr><tr><td>404 ban duration</td><td style="text-align:right;">0 hours (permanent)</td></tr><tr><td>Invalid API-key threshold in 24 hours</td><td style="text-align:right;">100</td></tr><tr><td>Invalid API-key ban duration</td><td style="text-align:right;">0 hours (permanent)</td></tr><tr><td>Repeat-offender limit</td><td style="text-align:right;">2 bans</td></tr></tbody></table><p>The authenticated Security dashboard can change the 404 threshold from 1 to 1,000, the invalid API-key threshold from 1 to 100, durations from 0 to 8,760 hours, and repeat limit from 1 to 10. A duration of zero means permanent.</p><p>When automatic banning is enabled and a tracker reaches its threshold, localhost addresses are never banned. The tracker resets after its 24-hour window. Existing ban records increment <code>ban_count</code>; reaching the configured repeat limit makes the ban permanent. Durations are not automatically doubled.</p><h2 id="dashboard-and-routes" tabindex="-1">Dashboard And Routes <a class="header-anchor" href="#dashboard-and-routes" aria-label="Permalink to &quot;Dashboard And Routes&quot;">​</a></h2><p>The React Security page is <code>/logs/security</code>. Session-authenticated routes are registered under <code>/security</code>:</p><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /security/</code></td><td>Older server-side dashboard template, still registered</td></tr><tr><td><code>POST /security/ban</code></td><td>Ban one validated IPv4/IPv6 address</td></tr><tr><td><code>POST /security/unban</code></td><td>Remove one ban</td></tr><tr><td><code>POST /security/ban-host</code></td><td>Resolve recent traffic for a validated host and ban matching IPs</td></tr><tr><td><code>POST /security/clear-404</code></td><td>Clear one 404 tracker</td></tr><tr><td><code>GET /security/api/data</code></td><td>Read ban/tracker/settings data</td></tr><tr><td><code>GET /security/stats</code></td><td>Read security totals</td></tr><tr><td><code>POST /security/settings</code></td><td>Update automatic-ban settings</td></tr><tr><td><code>GET /security/api/login-activity</code></td><td>Read login audit data</td></tr><tr><td><code>POST /security/api/login-activity/clear</code></td><td>Clear login audit data</td></tr><tr><td><code>GET /security/api/active-sessions</code></td><td>Read active application sessions</td></tr></tbody></table><p>There is no CIDR whitelist feature in the current middleware. Rate limiting and IP bans are separate controls.</p><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>utils/security_middleware.py</code></td><td>Pre-Flask ban enforcement</td></tr><tr><td><code>utils/ip_helper.py</code></td><td>Trusted client-IP resolution</td></tr><tr><td><code>database/traffic_db.py</code></td><td>Ban and attempt persistence</td></tr><tr><td><code>database/settings_db.py</code></td><td>Persisted thresholds and defaults</td></tr><tr><td><code>blueprints/security.py</code></td><td>Authenticated controls and data routes</td></tr><tr><td><code>frontend/src/pages/monitoring/SecurityDashboard.tsx</code></td><td>Current dashboard</td></tr></tbody></table>',22)])])}const b=e(o,[["render",i]]);export{p as __pageData,b as default};
